create or replace function public.create_presale_order(p_round_id uuid,p_purchase_value numeric,p_purchase_currency text) returns public.presale_orders language plpgsql security definer set search_path=public as $$ declare r public.presale_rounds%rowtype; o public.presale_orders%rowtype; uid uuid:=auth.uid(); ref text:='DTR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)); begin if uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if; select * into r from public.presale_rounds where id=p_round_id for share; if not found or r.status <> 'ACTIVE' then raise exception 'ROUND_NOT_ACTIVE' using errcode='P0001'; end if; if r.price_numeric is null or r.price_numeric <= 0 then raise exception 'PRICE_NOT_CONFIGURED' using errcode='P0001'; end if; insert into public.presale_orders(order_reference,investor_id,round_id,purchase_value,purchase_currency,locked_price_numeric,locked_price_currency,expected_dtr,expires_at,status) values(ref,uid,r.id,p_purchase_value,p_purchase_currency,r.price_numeric,coalesce(r.price_currency,p_purchase_currency),floor(p_purchase_value/r.price_numeric),coalesce(r.ends_at,now()+interval '24 hours'),'AWAITING_PAYMENT') returning * into o; return o; end; $$;
revoke all on function public.create_presale_order(uuid,numeric,text) from public; grant execute on function public.create_presale_order(uuid,numeric,text) to authenticated;

create or replace function public.submit_payment(p_order_id uuid,p_payment_route_id uuid,p_amount numeric,p_asset_code text,p_network_code text,p_transaction_hash text) returns public.payment_submissions language plpgsql security definer set search_path=public as $$ declare o public.presale_orders%rowtype; r public.payment_routes%rowtype; p public.payment_submissions%rowtype; uid uuid:=auth.uid(); begin if uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if; select * into o from public.presale_orders where id=p_order_id and investor_id=uid for update; if not found then raise exception 'ORDER_NOT_FOUND' using errcode='P0002'; end if; if o.status <> 'AWAITING_PAYMENT' then raise exception 'INVALID_ORDER_STATE' using errcode='P0001'; end if; if o.expires_at is not null and o.expires_at < now() then update public.presale_orders set status='EXPIRED',updated_at=now() where id=o.id; raise exception 'ORDER_EXPIRED' using errcode='P0001'; end if; select * into r from public.payment_routes where id=p_payment_route_id and round_id=o.round_id and active=true; if not found then raise exception 'PAYMENT_ROUTE_UNAVAILABLE' using errcode='P0001'; end if; if r.asset_code <> p_asset_code or r.network_code <> p_network_code then raise exception 'ROUTE_MISMATCH' using errcode='P0001'; end if; insert into public.payment_submissions(order_id,payment_route_id,amount,asset_code,network_code,transaction_hash,status) values(o.id,r.id,p_amount,p_asset_code,p_network_code,p_transaction_hash,'SUBMITTED') returning * into p; update public.presale_orders set status='PAYMENT_SUBMITTED',updated_at=now() where id=o.id; return p; exception when unique_violation then raise exception 'TRANSACTION_REFERENCE_ALREADY_SUBMITTED' using errcode='23505'; end; $$;
revoke all on function public.submit_payment(uuid,uuid,numeric,text,text,text) from public; grant execute on function public.submit_payment(uuid,uuid,numeric,text,text,text) to authenticated;
